-- 522: Original BrillaPrep NSMQ subj_nsmq_physics speed_race beta questions (batch 002).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_522_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_522_guard;
INSERT INTO _migration_522_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_sr_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_phys_electricity' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the SI unit of electrical resistance?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS 'Ohm' AND q.explanation IS 'The ohm (Ω) is the SI unit of electrical resistance; from Ohm’s law R = V/I, one ohm equals one volt per ampere. It is named after the German physicist Georg Simon Ohm.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_sr_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_522_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_sr_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_phys_waves' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What type of wave is a sound wave travelling through air?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS 'A longitudinal wave' AND q.explanation IS 'Sound in air travels as compressions and rarefactions in which the air particles oscillate parallel to the direction of energy transfer, which defines a longitudinal wave. Light, by contrast, is transverse.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_sr_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_522_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_sr_b002_003' AND NOT (q.topic_id IS 'topic_nsmq_phys_kinematics' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What physical quantity is given by the gradient of a velocity–time graph?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS 'Acceleration' AND q.explanation IS 'Acceleration is the rate of change of velocity, a = Δv/Δt, which is exactly the gradient (slope) of a velocity–time graph. The area under the same graph gives the displacement.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_sr_b002_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_522_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_sr_b002_004' AND NOT (q.topic_id IS 'topic_nsmq_phys_modern_physics' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which scientist proposed the mass–energy equivalence equation E = mc²?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS 'Albert Einstein' AND q.explanation IS 'Einstein published E = mc² in 1905 as a consequence of special relativity: mass and energy are equivalent, with c² (about 9 × 10¹⁶ m²/s²) as the conversion factor. It underpins nuclear energy and nuclear binding-energy calculations.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_sr_b002_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_sr_b002_001', 'topic_nsmq_phys_electricity', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'What is the SI unit of electrical resistance?', 'direct_answer', 'speed_race', NULL, 'Ohm', 'The ohm (Ω) is the SI unit of electrical resistance; from Ohm’s law R = V/I, one ohm equals one volt per ampere. It is named after the German physicist Georg Simon Ohm.', 'easy', '2', '1', '15', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, NULL);
