INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_sr_b002_003', 'topic_nsmq_phys_kinematics', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'What physical quantity is given by the gradient of a velocity–time graph?', 'direct_answer', 'speed_race', NULL, 'Acceleration', 'Acceleration is the rate of change of velocity, a = Δv/Δt, which is exactly the gradient (slope) of a velocity–time graph. The area under the same graph gives the displacement.', 'easy', '2', '1', '15', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_sr_b002_004', 'topic_nsmq_phys_modern_physics', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'Which scientist proposed the mass–energy equivalence equation E = mc²?', 'direct_answer', 'speed_race', NULL, 'Albert Einstein', 'Einstein published E = mc² in 1905 as a consequence of special relativity: mass and energy are equivalent, with c² (about 9 × 10¹⁶ m²/s²) as the conversion factor. It underpins nuclear energy and nuclear binding-energy calculations.', 'easy', '2', '1', '15', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, NULL);
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'nsmq-expansion-beta-002', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_nsmq_phys_sr_b002_001', 'q_nsmq_phys_sr_b002_002', 'q_nsmq_phys_sr_b002_003', 'q_nsmq_phys_sr_b002_004');
DELETE FROM _migration_522_guard;
